%% ============================================================
%% F6--F7: Interventions
%% ============================================================

\subsection{F6--F7: Interventions}
\label{sec:f6}

\paragraph{F6: $\dt{=}1$ imagination eliminates CIVO.}
\looseness=-1 Restricting imagination to $\dt{=}1$ while retaining the trained embedding (exp\_008e\_v3; Appendix~\ref{sec:code_corrections}) yields 0/4 CIVO (peak NVE ${\leq}0.8\times$); three seeds achieve $65$--$96\%$ of baseline (mean $775.6$; Figure~\ref{fig:multiple_pathways}). The embedding still receives gradients, but the critic never encounters biased $\dt{>}1$ predictions. This localizes the vulnerability: the temporal embedding enables co-adaptation, but $\dt{>}1$ rollouts are required to propagate bias into the critic.

\begin{figure}[t]
\centering
\includegraphics[width=\columnwidth]{figures/paper/fig6_multiple_pathways.pdf}
\caption{Contrasting dynamics ($2{\times}3$ grid). \textbf{Top row:} 008d (CIVO), showing eval collapse, value explosion, entropy decrease. \textbf{Bottom row:} 008e\_v3 s1 ($\dt{=}1$ imagination), no CIVO (NVE ${\leq}\,0.6\times$, eval $96\%$ baseline).}
\label{fig:multiple_pathways}
\end{figure}

\paragraph{F7: Full-pathway gradient stopping shows mixed results.}
\looseness=-1 Full-SGS (exp\_018) detaches all non-KL gradients from $e_{\dt}$. Seed~1 shows partial mitigation (eval 448.3, NVE $1.66\times$) with late instability---NVE rising from $1.23\times$ mean to $1.66\times$ at 95K---suggesting SGS delays rather than prevents onset; seed~2 collapses entirely (peak ${\sim}488$ at 75K $\to$ 40.8 at 105K; Appendix~\ref{sec:sgs_gradient_analysis}). The seed divergence indicates that full-SGS creates a metastable regime where stochastic factors determine whether delayed onset crosses the critical threshold within the training horizon. Cross-environment validation on Cheetah confirms CIVO generalization (010b, NVE $8.27$--$108.52\times$); full-SGS yields 0/3 elimination. Removing the embedding eliminates CIVO on Cheetah (024b, NVE $< 0.2\times$). Targeted obs-decoder-only SGS (exp\_025/026) achieves 1/6 prevention (1/4 Walker, 0/2 Cheetah; Table~\ref{tab:intervention_hierarchy}), confirming pathway redundancy: blocking the dominant gradient channel shifts co-adaptation to remaining pathways (Appendix~\ref{sec:seed_divergence}).

